/** Generated by scaffold-dashboard-pages. */
import { post } from '~/services/httpMethods';
import type { DashboardQuery, DashboardResult } from '~/types/ui';

/**
 * Parse the DSL string used in dashboards: list. Examples:
 *
 *   count:applications,where:createdAt>=today()
 *   count:applications,where:currentState=reviewing
 *   count:applications,group:currentState
 *   count:applications,group:day,window:30d
 */
export function parseDashboardQuery(dsl: string): DashboardQuery {
  const parts = dsl.split(',').map((p) => p.trim()).filter(Boolean);
  let entity = '';
  const where: DashboardQuery['where'] = [];
  let group: DashboardQuery['group'] | undefined;
  let pendingWindow: { days: number } | undefined;

  for (const part of parts) {
    const [key, ...rest] = part.split(':');
    const value = rest.join(':');
    if (key === 'count') {
      entity = value;
    } else if (key === 'where') {
      const m = value.match(/^(\w+)\s*(>=|<=|!=|=|>|<|LIKE|IN)\s*(.+)$/);
      if (!m) continue;
      const field = m[1];
      const op = m[2];
      let raw = m[3].trim();
      let parsed: unknown = raw;
      if (raw === 'today()') {
        const d = new Date();
        d.setHours(0, 0, 0, 0);
        parsed = d.toISOString();
      } else if (/^\d+$/.test(raw)) {
        parsed = Number(raw);
      } else if (/^'.+'$/.test(raw) || /^".+"$/.test(raw)) {
        parsed = raw.slice(1, -1);
      }
      where.push({ field, op, value: parsed });
    } else if (key === 'group') {
      group = { field: value };
    } else if (key === 'window') {
      const m = value.match(/^(\d+)d$/);
      if (m) pendingWindow = { days: Number(m[1]) };
    }
  }

  if (group && pendingWindow) group.window = pendingWindow;
  return { entity, op: 'count', where: where.length ? where : undefined, group };
}

export function runDashboardQuery(dsl: string): Promise<DashboardResult> {
  return post<DashboardResult>('/dashboard/query', parseDashboardQuery(dsl));
}

/** Query params accepted by the list thunk. */
export type FetchDashboardListParams = Record<string, unknown>;
